// E2E: notifications feature.
// Covers: unread badge in the header bell, dropdown list, mark-all-read,
// the /notifications page (tabs, mark one read, delete with confirmation),
// and engagement notifications generated by like/favorite.
const { registerUser, createTemplate, likeTemplate, unlikeTemplate, favoriteTemplate } = require('../helpers/api');

function loginViaUI(browser, email, password) {
  return browser
    .url(`${browser.launch_url}/login`)
    .waitForElementVisible('body', 15000)
    .execute(function () {
      try { localStorage.clear(); } catch (e) { /* ignore */ }
      localStorage.setItem('i18nextLng', 'en');
    })
    .url(`${browser.launch_url}/login`)
    .waitForElementVisible('#email', 15000)
    .setValue('#email', email)
    .setValue('#password', password)
    .submitForm('form');
}

describe('Notifications', function () {
  const owner = {};
  const actor = {};
  const template = {};

  before(function (browser, done) {
    (async () => {
      Object.assign(owner, await registerUser({ displayName: 'Notif Owner' }));
      Object.assign(actor, await registerUser({ displayName: 'Notif Actor' }));
      const t = await createTemplate(owner.token, { title: 'Notif E2E Template' });
      Object.assign(template, t);
      // Like + favorite create engagement notifications for the owner.
      await likeTemplate(actor.token, t.id);
      await favoriteTemplate(actor.token, t.id);
      done();
    })().catch(done);
  });

  after(function (browser) {
    browser.end();
  });

  it('shows the unread badge and dropdown after engagement', function (browser) {
    loginViaUI(browser, owner.email, owner.password)
      .waitForElementVisible('.notification-bell-btn', 20000);

    // The first poll fires 60s after mount; a window focus event forces an
    // immediate fetch when the last fetch is stale.
    browser
      .execute(function () { window.dispatchEvent(new Event('focus')); })
      .waitForElementVisible('.notification-badge', 15000)
      .assert.textContains('.notification-badge', '2');
  });

  it('lists notifications in the dropdown and marks all read', function (browser) {
    browser
      .click('.notification-bell-btn')
      .waitForElementVisible('.notification-dropdown', 10000)
      .assert.visible('.notification-dropdown-mark-all')
      .assert.textContains('.notification-dropdown-list', 'liked your template')
      .assert.textContains('.notification-dropdown-list', 'favorited your template')
      .assert.textContains('.notification-dropdown-list', template.title);

    browser
      .click('.notification-dropdown-mark-all')
      .waitForElementNotPresent('.notification-badge', 15000)
      .waitForElementNotPresent('.notification-dropdown-mark-all', 15000);
  });

  it('shows a fresh unread notification on the notifications page', function (browser) {
    // Unlike + re-like generates a new unread notification for the owner.
    browser.perform(async (done) => {
      try {
        await unlikeTemplate(actor.token, template.id);
        await likeTemplate(actor.token, template.id);
        done();
      } catch (err) {
        done(err);
      }
    });

    browser
      .url(`${browser.launch_url}/notifications`)
      .waitForElementVisible('.notifications-page', 20000)
      .assert.visible('.notification-item.unread')
      .assert.textContains('.notifications-list', 'liked your template');

    // Unread tab shows only unread items.
    browser
      .useXpath()
      .click('//button[contains(@class, "filter-tab")][contains(., "Unread")]')
      .useCss()
      .waitForElementVisible('.notifications-list', 10000)
      .assert.visible('.notification-item.unread');
  });

  it('marks a single notification read from the page', function (browser) {
    browser
      .waitForElementVisible('.notification-item.unread .notification-action.mark-read', 10000)
      .click('.notification-item.unread .notification-action.mark-read')
      .waitForElementNotPresent('.notification-item.unread', 15000);
  });

  it('deletes a notification after confirming', function (browser) {
    browser
      .useXpath()
      .click('//button[contains(@class, "filter-tab")][contains(., "All")]')
      .useCss()
      .waitForElementVisible('.notification-item', 10000);

    const before = {};
    browser.execute(
      function () { return document.querySelectorAll('.notification-item').length; },
      [],
      (result) => { before.count = result.value; }
    );

    browser
      .click('.notification-item .notification-action.delete')
      .waitForElementVisible('.modal-overlay', 10000)
      .click('.modal-footer .btn-danger')
      .waitForElementNotPresent('.modal-overlay', 15000)
      .pause(500)
      .execute(
        function () { return document.querySelectorAll('.notification-item').length; },
        [],
        (result) => {
          browser.assert.strictEqual(
            result.value,
            before.count - 1,
            'notification count decreases by one after delete'
          );
        }
      );
  });
});
